insert into public.ark60_content(day_number,module,title,status,payload,published_at,updated_at) values(11,'listening','Full Mock · Listening · Volume 10 Test 4','draft','{"version":"oct11-full-mock-listening-vol10-test4-v1","test_code":"VOLUME-10-TEST-4","mock_day":11,"audio_url":"https://ia600900.us.archive.org/24/items/volume-10-listening-test-4-full-audio/Volume%2010%20Listening%20Test%204%20-%20Full%20Audio.mp3","total_questions":40,"audio_once":true,"sections":[{"number":1,"label":"SECTION 1","range":"Questions 1–10","blocks":[{"kind":"table","range":"Questions 1–10","instruction":"Complete the table below.","word_limit":"Write NO MORE THAN TWO WORDS/NUMBERS for each answer.","title":"Campground Information","headers":["Name of campground","Location","Special features","Other comments"],"rows":[[["Diamond Head"],["It''s near the beach."],["Near the entrance, there''s a ",{"q":1},"."],["It can get busy – in summer, you need to book ",{"q":2}," in advance. ",{"q":3}," are necessary to use the washing machines but not the showers."]],[["Cedar Grove"],["It''s beside a ",{"q":4},"."],["Suitable for children. There’s a large ",{"q":5}," to explore."],["There are no sheltered facilities for ",{"q":6},". For safety, campers need to bring their own ",{"q":7},"."]],[["Wattle Ridge"],["It''s in a remote location, close to Wattle ",{"q":8},"."],["Guided tours by park rangers."],["It''s ",{"q":9}," kilometres away from the city. A good place to visit is ",{"q":10}," Falls."]]]}]},{"number":2,"label":"SECTION 2","range":"Questions 11–20","blocks":[{"kind":"choose_two","range":"Questions 11–12","instruction":"Choose TWO correct answers, A–E.","question":"Which TWO things can visitors do at the new Dinosaur Exhibition?","questions":[11,12],"options":{"A":"climb on some of the models","B":"stay overnight near the dinosaurs","C":"help to make a model of a dinosaur","D":"be in a movie with dinosaurs","E":"watch some of the models moving"}},{"kind":"choose_two","range":"Questions 13–14","instruction":"Choose TWO correct answers, A–E.","question":"Which TWO things can visitors do in the International Art Exhibition?","questions":[13,14],"options":{"A":"take pictures of the works of art","B":"vote for their favourite artwork","C":"buy some of the works of art","D":"see a range of sculptures","E":"talk to one of the artists"}},{"kind":"matching","range":"Questions 15–20","instruction":"Label the map below.","word_limit":"Choose the correct letter, A–I, next to questions 15–20.","title":"Bankside Cultural Complex","image_url":"/listening/volume10-test4-bankside.png","image_alt":"Bankside Cultural Complex map with locations A to I","hide_choices":true,"choices":{"A":"A","B":"B","C":"C","D":"D","E":"E","F":"F","G":"G","H":"H","I":"I"},"items":[{"q":15,"text":"Information Centre"},{"q":16,"text":"Library"},{"q":17,"text":"Museum"},{"q":18,"text":"Art Gallery"},{"q":19,"text":"Restaurant"},{"q":20,"text":"BBQ area"}]}]},{"number":3,"label":"SECTION 3","range":"Questions 21–30","blocks":[{"kind":"mcq","range":"Questions 21–25","instruction":"Choose the correct letter, A, B or C.","questions":[{"q":21,"text":"In preparation for the field trip, Andrew and Molly have","options":{"A":"produced a letter.","B":"received permission to visit a pond.","C":"checked Health and Safety requirements."}},{"q":22,"text":"Andrew and Molly have decided against giving worksheets on the field trip because","options":{"A":"they don''t want the activity to be too structured.","B":"they want the children to focus on collecting specimens.","C":"they don''t think there will be enough time."}},{"q":23,"text":"In their third lesson, what''s the purpose of the picture activity?","options":{"A":"The children practice drawing and labelling.","B":"The children identify the food chain in the pond.","C":"The children learn the names of pond creatures."}},{"q":24,"text":"Why does the professor suggest a follow-up activity?","options":{"A":"to give the children speaking practice","B":"to introduce the topic of mammals","C":"to provide variation in the lesson"}},{"q":25,"text":"Andrew and Molly plan to use a movie instead of a live animal in the last lesson, because it will be more","options":{"A":"practical.","B":"effective.","C":"motivating."}}]},{"kind":"matching","range":"Questions 26–30","instruction":"Complete the flow-chart below.","word_limit":"Choose FIVE correct answers, A–H, next to questions 26–30.","title":"Plan for last lesson: (class) watch a movie → (small groups) have a discussion","choices":{"A":"ask questions","B":"complete a worksheet","C":"do a drawing","D":"listen to the teachers","E":"make a list","F":"observe a live animal","G":"report ideas","H":"spell key words"},"items":[{"q":26,"text":"(class)"},{"q":27,"text":"(pairs)"},{"q":28,"text":"(class)"},{"q":29,"text":"(individuals)"},{"q":30,"text":"(individuals)"}]}]},{"number":4,"label":"SECTION 4","range":"Questions 31–40","blocks":[{"kind":"notes_groups","range":"Questions 31–40","instruction":"Complete the notes below.","word_limit":"Write ONE WORD ONLY for each answer.","title":"Maori Middens","groups":[{"heading":"General information","items":[["Midden: rubbish dump"],["Studying middens in New Zealand reveals information"]]},{"heading":"Contains","items":[["Food scraps (mainly seashells)"],["A broken ",{"q":31}],["Some hooks made of ",{"q":32}],["If you want to study a midden, you need to get a ",{"q":33}]]},{"heading":"Research findings","items":[["Middens can be found on the beach, but erosion is important"],["It is hard to find a midden where a ",{"q":34}," is being built"],["It can offer information on the ",{"q":35}," pattern of those Maori"]]},{"heading":"Dietary habit","items":[["Early Maori ate ",{"q":36}," (very fatty)"],["Later Maori ate fish (not fatty)"]]},{"heading":"More findings","items":[["Shell middens can be found close to the beaches and ",{"q":37}],["Middens can be found in the South Island, but are very ",{"q":38}],["European middens contained ",{"q":39}," objects"],["Large European middens were found in the places where ",{"q":40}," stayed"]]}]}]}],"answer_key":{"1":["cafe","café"],"2":["six months","6 months"],"3":["coins"],"4":["river"],"5":["cave"],"6":["cooking"],"7":["water"],"8":["Mountain"],"9":["275"],"10":["Coolaby"],"11":["B"],"12":["D"],"13":["A"],"14":["C"],"15":["I"],"16":["E"],"17":["B"],"18":["G"],"19":["C"],"20":["A"],"21":["B"],"22":["A"],"23":["B"],"24":["C"],"25":["A"],"26":["D"],"27":["E"],"28":["G"],"29":["B"],"30":["C"],"31":["axe","ax"],"32":["bone"],"33":["permit"],"34":["road"],"35":["migration"],"36":["birds"],"37":["lakes"],"38":["rare"],"39":["glass"],"40":["soldiers"]},"pair_groups":{"11-12":{"questions":[11,12],"correct":["B","D"]},"13-14":{"questions":[13,14],"correct":["A","C"]}}}'::jsonb,null,now()) on conflict(day_number,module) do update set title=excluded.title,status='draft',payload=excluded.payload,published_at=null,updated_at=now();

insert into public.ark60_content(day_number,module,title,status,payload,published_at,updated_at) values(11,'writing','Full Mock · Writing Task 1 + Task 2','draft','{"version":"oct11-full-mock-writing-333-v1","mock":true,"duration_seconds":3600,"tasks":[{"task_type":"task1","label":"Writing Task 1","recommended_seconds":1200,"min_words":150,"prompt":"The table compares the number of students choosing five different subjects in 2005, 2010, and 2015, and also shows the percentage change over the ten-year period.","instructions":["Summarize the information by selecting and reporting the main features, and make comparisons where relevant."],"visual":{"kind":"table","title":"Students choosing five subjects, 2005–2015","headers":["Subjects","2005","2010","2015","% Change from 2005–2015"],"rows":[["Information Technology (IT)","410","550","620","+51%"],["Spanish","210","200","220","+5%"],["History","90","70","70","−22%"],["Fashion studies","90","100","120","+33%"],["Business studies","110","210","225","+105%"]]}},{"task_type":"task2","label":"Writing Task 2","recommended_seconds":2400,"min_words":250,"prompt":"People often rely on their cars for daily, work-related, and personal travel. However, the increasing number of private cars has led to several problems.\n\nWhat are these problems, and what measures can be taken to discourage people from using their cars?","instructions":["Give reasons for your answer and include any relevant examples from your own knowledge or experience."]}]}'::jsonb,null,now()) on conflict(day_number,module) do update set title=excluded.title,status='draft',payload=excluded.payload,published_at=null,updated_at=now();

insert into public.ark60_reading_passages(day_number,ordinal,title,passage_text,question_source,questions,answer_key,status,analysis) values(11,1,'Antonio Stradivari - Violin Maker Supreme','From the 1670s onwards, the violin maker Antonio Stradivari (1644-1737) successfully applied his inspired vision and enormous attention to detail to the artistic and commercial challenges of running an international high-art workshop from his base of operations in Cremona, Italy. The challenges of responding to the demands of the musical elite in Europe at the time would have been substantial, with all of the associated problems of transportation, communication, currency exchange, acquiring materials and sustaining a productive workshop at a high technical level.

But Stradivari was clearly capable of meeting these demands and his violins became the dominant force in string-instrument building in Europe from 1700 to his death in 1737. Somewhat lower production levels from the Stradivari workshop after 1727 left a gap in Cremona that was filled in the main by the Italian violin maker Bartolomeo Giuseppe Guarneri (1698-1744). Nonetheless, in most years, both in terms of quantity and the quality of material and finished product, the output from the Stradivari workshop exceeded that of all the other instrument makers in Cremona combined.

Production from the Stradivari workshop began to accelerate toward a historical high point after 1700. Between 1709 and 1717 or so, the workshop mainly produced instruments based on Stradivari''s most celebrated models. Exceptional levels of craftsmanship were combined with an extraordinary consistency of production. The year 1715, when the Lipinski model of Stradivari was built, is considered by many to be the height of classical stringed instrument making. Between 1714 and 1716, the workshop was producing an astonishing 16 instruments or more annually, using the finest materials available anywhere and designed along the boldest patterns ever conceived of for stringed instruments. The instruments represented a fusion of a bold idea with unprecedented focus on materials and finishes.

The origins of the Stradivari approach to production are not always readily apparent: that Stradivari would have encountered the earlier violin forms of the Amati and Rugeri families in Cremona is to be expected, and the influence of traditional Cremonese methods is in evidence even in his earliest works. That Stradivari may have encountered other instruments, and how they may have influenced future designs, is largely a matter of speculation.

Whether by direct influence or his own inventiveness, in the 1690s Stradivari experimented with improvements to the forms with which he began his career. In particular, he began experimenting with a longer form than that of contemporary makers in Cremona. This may have been informed by the larger instruments produced by instrument makers from the Brescian region of Italy, such as Giovanni Paolo Maggini (c.1580-c.1630), which were already considered antiques in Stradivari''s day. Functionally, Stradivari''s so-called Long Pattern instruments from this period recall some of the deeper sound produced by the Brescian models.

No historical record indicating Stradivari''s awareness of older forms has come to light, so we can only guess at what may have directly influenced the development of his designs. Whatever the influences were, he discarded the Long Pattern model in 1699, but a decade later returned to forms of larger dimensions.

The larger violins that began to appear around 1709 are of similar length to the Long Pattern instruments but were generally broader throughout, creating an unprecedented amount of airspace within the violin. The arching on the fronts and backs of these violins produced some of the greatest violins ever created.

Stradivari was substantially ahead of his time with his creations. The large performance venues that are the norm today were unheard of in the 1700s, and the power and brilliance of his mature instruments explain the presence of the solo violin in a modern, 3,000-seat concert hall. One can only wonder what course music performance might have taken had his violins never been invented.

In the decades and centuries after they were built, as concerts took place in increasingly large public venues, Stradivari''s violins, like the Lipinski and its close cousins, the Hochstein and the Cremonese, helped make music available to a broader class of citizens beyond just the aristocracy.

Stradivari instruments have proven demonstrably superior to all attempts at replication: although it has been some 300 years since their creation, Stradivari instruments remain in use in modern concert halls as the choice of contemporary artists, to the benefit of audiences. For this reason, Stradivari instruments are unique among art objects and there is no craftsman more worthy of the unchallenged reputation that Antonio Stradivari enjoys.','IELTS Reading — Volume 10 Test 6','[{"number":1,"type":"tfng","text":"Stradivari was a good businessman as well as a craftsman.","instruction":"Questions 1–7 · TRUE / FALSE / NOT GIVEN","options":["TRUE","FALSE","NOT GIVEN"]},{"number":2,"type":"tfng","text":"The majority of the musical elite wanted the same model of violin.","instruction":"Questions 1–7 · TRUE / FALSE / NOT GIVEN","options":["TRUE","FALSE","NOT GIVEN"]},{"number":3,"type":"tfng","text":"Stradivari produced fewer violins between 1727 and his death in 1737.","instruction":"Questions 1–7 · TRUE / FALSE / NOT GIVEN","options":["TRUE","FALSE","NOT GIVEN"]},{"number":4,"type":"tfng","text":"Bartolomeo Giuseppe Guarneri attempted to use Stradivari''s ideas.","instruction":"Questions 1–7 · TRUE / FALSE / NOT GIVEN","options":["TRUE","FALSE","NOT GIVEN"]},{"number":5,"type":"tfng","text":"Other violin companies in Cremona consistently produced violins in greater quantity than the Stradivari workshop.","instruction":"Questions 1–7 · TRUE / FALSE / NOT GIVEN","options":["TRUE","FALSE","NOT GIVEN"]},{"number":6,"type":"tfng","text":"Between 1709 and 1717, the Stradivari workshop focused on a few very famous designs.","instruction":"Questions 1–7 · TRUE / FALSE / NOT GIVEN","options":["TRUE","FALSE","NOT GIVEN"]},{"number":7,"type":"tfng","text":"It''s likely that Stradivari came across the violins made by the Amati and Rugeri families.","instruction":"Questions 1–7 · TRUE / FALSE / NOT GIVEN","options":["TRUE","FALSE","NOT GIVEN"]},{"number":8,"type":"gap","text":"Certain influences in the 1690s led to Stradivari making ________ designs to his initial violins.","instruction":"Questions 8–13 · Italian Violin Makers · ONE WORD AND/OR A NUMBER from the passage"},{"number":9,"type":"gap","text":"Large violins from Brescia were thought to be ________.","instruction":"Questions 8–13 · Italian Violin Makers · ONE WORD AND/OR A NUMBER from the passage"},{"number":10,"type":"gap","text":"The sound produced by the Brescian violins was ________ than that of other violins.","instruction":"Questions 8–13 · Italian Violin Makers · ONE WORD AND/OR A NUMBER from the passage"},{"number":11,"type":"gap","text":"Stradivari stopped making Long Pattern instruments sometime during ________.","instruction":"Questions 8–13 · Italian Violin Makers · ONE WORD AND/OR A NUMBER from the passage"},{"number":12,"type":"gap","text":"Stradivari made ________ violin performances in large concert halls possible.","instruction":"Questions 8–13 · Italian Violin Makers · ONE WORD AND/OR A NUMBER from the passage"},{"number":13,"type":"gap","text":"No other craftsman has managed to equal the ________ that Stradivari has gained.","instruction":"Questions 8–13 · Italian Violin Makers · ONE WORD AND/OR A NUMBER from the passage"}]'::jsonb,'[["TRUE"],["NOT GIVEN"],["TRUE"],["NOT GIVEN"],["FALSE"],["TRUE"],["TRUE"],["LONGER"],["ANTIQUES"],["DEEPER"],["1699"],["SOLO"],["REPUTATION"]]'::jsonb,'draft','[]'::jsonb) on conflict(day_number,ordinal) do update set title=excluded.title,passage_text=excluded.passage_text,question_source=excluded.question_source,questions=excluded.questions,answer_key=excluded.answer_key,status='draft',analysis=excluded.analysis;

insert into public.ark60_reading_passages(day_number,ordinal,title,passage_text,question_source,questions,answer_key,status,analysis) values(11,2,'Antarctic Architecture: Halley VI','Inspired by science fiction, the Halley VI Research Station has a lot to teach about how architecture can impact psychology

A One morning in 2004, Hugh Broughton was listening to the radio when two voices caused him to pay attention. One of them he recognised through his work as an architect. It was the President of the Royal Institute of British Architects, George Ferguson. The other was less familiar: the director of the British Antarctic Survey, Chris Rapley. The two were announcing a competition to design a new research station in Antarctica. It was a job, they explained, that presented an unusual set of challenges. The site of the new structure was on floating ice 50 kilometres from the Antarctic mainland. Previous stations built in the vicinity had recorded temperatures as low as -50 degrees Celsius and winds of up to 160 kilometres an hour. Only one had escaped the fate of being completely engulfed by snow and abandoned. But it too was now in jeopardy. Ferguson and Rapley listed a number of criteria that they''d be looking for: a background in building in remote locations, knowledge of extreme climates, and an understanding of complex logistics. Broughton ticked zero of those boxes, but that didn''t prevent him from entering the competition – and winning it.

B The structure that Broughton designed, which was completed in 2012, is called Halley VI. It''s made of eight conjoined pods, raised above the snow by hydraulic legs at the feet of which is a set of massive skis, allowing the entire station to be moved by bulldozers. It doesn''t surprise Broughton that people often use film references to describe his creation. He openly admits that science fiction from the 1960s was a big influence. Of course, a few of Broughton''s ideas had to be tempered when he learned more about the challenges associated with building near the South Pole. He realised that, in a year, only the 12 weeks of summer were suitable for construction work, meaning most of the base had to be prefabricated in South Africa, transported by ship and then built over a few summer seasons. No single element could weigh more than 9 tonnes, lest it fall through the ice during transportation. There was also the matter of complying with the Antarctic Treaty, which governs all activity on the icy continent. The rule outlawing the introduction of any non-indigenous plant life, for example, meant that plans to plant salad vegetables in a garden in the station had to be abandoned.

C Still, Broughton managed to navigate these challenges and enlisted the help of a colour expert to devise a palette that was bright, but not overpowering. Lebanese cedar, which gives off a natural fragrance, was used around parts of the station to combat sensory deprivation. As well, Broughton worked with a team to develop special lighting that simulates the sun''s rhythms; the aim was to mitigate seasonal affective disorder (winter depression) during the 105 days a year in which there is no daylight. Few appreciate the impact of these innovations more than Tom Welsh, Halley VI''s winter station leader. ''During the winter, you can''t really get out and do very much,'' he says. ''So you really rely on getting your mental stimulus from inside the station.'' The large central module is key for this function. It''s where staff meet to watch movies, eat and play pool. Welsh''s team has even constructed a small mini golf course there.

D Life at Halley VI isn''t all fun and games. There''s also the job of conducting research into topics ranging from space weather to ozone levels. Some of this work is done on a purpose-built observation deck atop the northernmost module. The station''s triple-glazed windows and heating system normally keep the temperature fairly moderate, but they''re not completely foolproof. In 2014, a power outage left the entire station exposed to record low temperatures for 19 hours. It was so cold that when someone threw a cup of boiling water in the air, it instantly turned into a cloud of ice crystals.

E Thankfully, the entire crisis was eventually brought under control, and no one was hurt. But it gave Halley VI''s team a taste of what life was like for pioneering Antarctic explorers at the start of the 20th century. Back then, research stations provided the bare essentials of survival. They were usually dirty, stuffy places, where tempers flared and the divisions in ranks were strictly maintained. ''There were definitely a lot of people living in very close contact with each other,'' says Pip Cheshire, a New Zealand architect who has helped restore a number of old Antarctic huts. ''There are a few cases of explorers actually succumbing to "cabin fever" in these harsh surroundings.''

F It''s difficult to imagine such bleakness on Halley VI. Here, every measure is taken to make its crew comfortable. Broughton is now seen as an expert in designing research bases, and was commissioned to design a new facility for the Spanish Antarctic programme. NASA also reached out for guidance on how to build stations for long-range space missions. ''They''ve asked questions like, "How small were the sleeping quarters and what features did you introduce to give them individual personality?"'' he says. ''They''re interested in how architecture can contribute to psychological wellbeing during long periods of isolation.''

G For Sam Jacob, a London-based architect and writer who recently wrote a foreword for a book about Antarctic architecture, applying Broughton''s ideas to space travel makes sense. ''Antarctica is the place on Earth that is the least like Earth, if you know what I mean – it''s the place most like another planet,'' he says. ''So, with that in mind, you can really imagine Halley sitting on a planet in outer space. It''s something that''s not only informed by science fiction, but could also give an idea of how we might actually colonise other places.''','IELTS Reading — Volume 10 Test 6','[{"number":14,"type":"select","text":"a description of living conditions in the early days of Antarctic exploration","instruction":"Questions 14–18 · Match sections A–G. You may use any letter more than once.","options":["A","B","C","D","E","F","G"]},{"number":15,"type":"select","text":"examples of consultants who helped Broughton provide pleasant surroundings on Halley VI","instruction":"Questions 14–18 · Match sections A–G. You may use any letter more than once.","options":["A","B","C","D","E","F","G"]},{"number":16,"type":"select","text":"a description of a time when technical failure led to an emergency situation","instruction":"Questions 14–18 · Match sections A–G. You may use any letter more than once.","options":["A","B","C","D","E","F","G"]},{"number":17,"type":"select","text":"information about Broughton''s lack of experience before he designed Halley VI","instruction":"Questions 14–18 · Match sections A–G. You may use any letter more than once.","options":["A","B","C","D","E","F","G"]},{"number":18,"type":"select","text":"a reference to recreational activities on Halley VI","instruction":"Questions 14–18 · Match sections A–G. You may use any letter more than once.","options":["A","B","C","D","E","F","G"]},{"number":19,"type":"gap","text":"The station Broughton designed consists of ________ that are linked together.","instruction":"Questions 19–22 · Construction of Halley VI · ONE WORD ONLY from the passage"},{"number":20,"type":"gap","text":"These are attached to skis and so can be transported using ________.","instruction":"Questions 19–22 · Construction of Halley VI · ONE WORD ONLY from the passage"},{"number":21,"type":"gap","text":"Building work could only take place on the site in ________.","instruction":"Questions 19–22 · Construction of Halley VI · ONE WORD ONLY from the passage"},{"number":22,"type":"gap","text":"Pieces of the structure were made off-site and brought in by ________.","instruction":"Questions 19–22 · Construction of Halley VI · ONE WORD ONLY from the passage"},{"number":23,"type":"select","text":"Living conditions on stations in Antarctica used to be crowded.","instruction":"Questions 23–26 · Match people A–D. You may use any letter more than once.","options":["A George Ferguson and Chris Rapley","B Tom Welsh","C Pip Cheshire","D Sam Jacob"]},{"number":24,"type":"select","text":"Antarctica is different from everywhere else in the world.","instruction":"Questions 23–26 · Match people A–D. You may use any letter more than once.","options":["A George Ferguson and Chris Rapley","B Tom Welsh","C Pip Cheshire","D Sam Jacob"]},{"number":25,"type":"select","text":"The project would require an architect who had done similar work before.","instruction":"Questions 23–26 · Match people A–D. You may use any letter more than once.","options":["A George Ferguson and Chris Rapley","B Tom Welsh","C Pip Cheshire","D Sam Jacob"]},{"number":26,"type":"select","text":"The station may provide a sense of how to build in difficult locations elsewhere.","instruction":"Questions 23–26 · Match people A–D. You may use any letter more than once.","options":["A George Ferguson and Chris Rapley","B Tom Welsh","C Pip Cheshire","D Sam Jacob"]}]'::jsonb,'[["E"],["C"],["D"],["A"],["C"],["PODS"],["BULLDOZERS"],["SUMMER"],["SHIP"],["C"],["D"],["A"],["D"]]'::jsonb,'draft','[]'::jsonb) on conflict(day_number,ordinal) do update set title=excluded.title,passage_text=excluded.passage_text,question_source=excluded.question_source,questions=excluded.questions,answer_key=excluded.answer_key,status='draft',analysis=excluded.analysis;

insert into public.ark60_reading_passages(day_number,ordinal,title,passage_text,question_source,questions,answer_key,status,analysis) values(11,3,'Lawrence Johnston and Hidcote Garden','Robin Lane Fox writes about the American genius behind a remarkable garden in the English Cotswolds

A Today, the National Trust in the UK administers hundreds of public gardens, while sixty years ago there was only one, Hidcote Manor near the English village of Chipping Campden. In 1949 Hidcote attracted a mere 600 visitors and took all of £30 during its first public season. Nowadays, Hidcote is famous worldwide as a masterpiece of design and planting, attracting 150,000 visitors and raising nearly £1 million from entrance tickets annually.

B Hidcote Garden was the creation of an American in Britain, the shy Major Lawrence Johnston, who came to live on the site in 1907 with his widowed mother, Gertrude Winthrop. In some respects Winthrop feared her son''s talents for expensive landscape gardening and never allowed him full access to the family''s funds. Nonetheless, with her inspiration and guidance Johnston started his design in 1908 and brought it to a peak in the early 1930s when he was in his 60s. He may rightly be ranked at this time beside Harold Nicolson and Vita Sackville-West, creators of Sissinghurst, his garden''s only surviving equal.

C In the last years of his life, Johnston placed faith in his head gardener Nancy Lindsay. Lindsay was undoubtedly a skilled plantswoman but she had many other talents as well, including one for taking offence, and she was ill-suited to dealing with her impassioned views. When the National Trust subsequently acquired the garden from Johnston, none of his crucial garden diaries could be found, and some speculated that Lindsay had burned them to hurt her employer. Whatever their actual fate, Trust gardener Graham Thomas was tasked with reviving Hidcote, and he had to manage without these crucial documents. Thomas knew that for the gardens to be a commercial success he needed to extend those areas that were of most interest to the general public, so he introduced new plants and a Mediterranean Bank where Johnston had had nothing of the sort, while retaining the existing superb structure of avenues and evergreen rooms. As a result, since 1949, the visiting public has innocently been admiring Thomas''s flower plantings, not Johnston''s own. When the important designer Russell Page had visited Hidcote in 1934 he had hailed the half-hardy plants in the summer house as one of the highlights. But Thomas later got rid of them and pulled the house down, fearing such relatively colourless exhibits would not capture the public''s imagination.

D Then, in 2002, Johnston''s old diaries and notebooks resurfaced. The present head gardener had started to give lectures about Hidcote''s lost early designs, during which he appealed for memories from his audience. A few months later an envelope arrived. There was no letter inside, only Johnston''s personal diaries from the 1920s and 30s. The sender may be unknown but the importance of these documents to Hidcote is certain, for they contain invaluable notes regarding the selection of plants and, even better still, detailed sketches by Johnston himself showing how the different parts of the garden are related and how those relationships evolve over the seasons. These documents are a rarity in other ways too, for they never dwell on the issues so typically addressed in diaries – relationships, loves and longings. These are far more interesting, for they represent a classic social history of an English country house during the inter-war years.

E On page after page Johnston describes the layout of the plants and gardens, interspersed, for example, with that day''s guests. The famous novelist Edith Wharton is recorded as coming for lunch, beside a recipe for poison to kill garden weeds. It is this mix of glamour and the everyday that makes the diaries of such peculiar fascination. At their heart, though, these are useful documents containing, for example, lengthy lists of those who might one day be of service around the estate, including local stone masons and glaziers, or repairers of broken china from as far away as France.

F The discovery of the diaries has offered Hidcote a new direction for the years ahead. Inspired by them, an anonymous American has given the gardens £1.6 million. This is a remarkable chance, which the Trust has gladly seized upon to allow for crucial repair work on paths and the famous pool, together with the reconstruction of the old summer house. However, the real implications of the discoveries made from the diaries are more problematic, for now the Trust must take its collection of plants up one notch. We now possess information about the very plants that most appealed to Johnston in the garden''s golden years. Today, these may not be easy to source, nor so appealing to contemporary tastes.

G ''But isn''t it all so long ago?'', a non-gardening academic recently asked me. On the contrary, Hidcote is still with us, a living legacy. It includes the greatest central vista in British gardening, the design I regard as the greatest in British art in the past century. It was the work of an American genius building an un-American garden of his own. I do not believe the fashionable guess nowadays that Johnston was informed by books on contemporary design by Britain''s Thomas Mawson, an altogether less innovative mind. This is not least because there is so much in the garden to remind us of how Johnston had travelled widely in Europe, which Mawson had not. It is Johnston''s own origins, the events of his life, and his individual design flair that contribute to making Hidcote so unique.','IELTS Reading — Volume 10 Test 6','[{"number":27,"type":"mcq","text":"What does the writer say about Hidcote Garden in the first paragraph?","instruction":"Questions 27–31 · Choose A, B, C or D","options":["A It is the most popular with overseas visitors.","B Its popularity has increased over the years.","C It has increased in size since first opening.","D It is the largest garden administered by the National Trust."]},{"number":28,"type":"mcq","text":"The writer refers to the Sissinghurst garden in order to","instruction":"Questions 27–31 · Choose A, B, C or D","options":["A illustrate Hidcote''s significance.","B highlight two of Johnston''s critics.","C identify one of Johnston''s inspirations.","D compare Hidcote to a garden that no longer exists."]},{"number":29,"type":"mcq","text":"What does the writer suggest about Nancy Lindsay?","instruction":"Questions 27–31 · Choose A, B, C or D","options":["A She was injured in an accident.","B She was head gardener after Johnston''s death.","C She lacked the necessary gardening talent.","D She may have had a disagreement with Johnston."]},{"number":30,"type":"mcq","text":"According to the writer, which of the following is true about Graham Thomas?","instruction":"Questions 27–31 · Choose A, B, C or D","options":["A The public does not realise the extent of his contribution to the garden.","B He did not have a sufficiently commercial mind.","C He revived the garden based on the diaries.","D The public disliked his part of the garden."]},{"number":31,"type":"mcq","text":"The writer refers to Russell Page in order to","instruction":"Questions 27–31 · Choose A, B, C or D","options":["A evaluate Thomas''s work.","B criticise one of Thomas''s rivals.","C give an example of Thomas''s approach.","D correct a common mistake about Thomas."]},{"number":32,"type":"select","text":"As a result of talks of the garden''s ________, Johnston''s diaries were returned by an anonymous source.","instruction":"Questions 32–36 · The Discovery of Johnston''s Diaries · Choose A–I","options":["A drawings","B plantings","C private life","D original plans","E opportunities","F craftsmen","G visitors","H future","I poems"]},{"number":33,"type":"select","text":"Most valuable of all for today’s gardeners at Hidcote were ________ revealing how the garden changed in the course of the year.","instruction":"Questions 32–36 · The Discovery of Johnston''s Diaries · Choose A–I","options":["A drawings","B plantings","C private life","D original plans","E opportunities","F craftsmen","G visitors","H future","I poems"]},{"number":34,"type":"select","text":"From the diaries, we learn little of Johnston''s ________.","instruction":"Questions 32–36 · The Discovery of Johnston''s Diaries · Choose A–I","options":["A drawings","B plantings","C private life","D original plans","E opportunities","F craftsmen","G visitors","H future","I poems"]},{"number":35,"type":"select","text":"They contain stories of well-known ________.","instruction":"Questions 32–36 · The Discovery of Johnston''s Diaries · Choose A–I","options":["A drawings","B plantings","C private life","D original plans","E opportunities","F craftsmen","G visitors","H future","I poems"]},{"number":36,"type":"select","text":"They contain practical information, like how to contact ________ in a foreign country.","instruction":"Questions 32–36 · The Discovery of Johnston''s Diaries · Choose A–I","options":["A drawings","B plantings","C private life","D original plans","E opportunities","F craftsmen","G visitors","H future","I poems"]},{"number":37,"type":"tfng","text":"Gardening may be considered a form of art.","instruction":"Questions 37–40 · YES / NO / NOT GIVEN","options":["YES","NO","NOT GIVEN"]},{"number":38,"type":"tfng","text":"The original design of Hidcote should be retained as closely as possible.","instruction":"Questions 37–40 · YES / NO / NOT GIVEN","options":["YES","NO","NOT GIVEN"]},{"number":39,"type":"tfng","text":"Mawson was the most significant influence on Johnston''s work.","instruction":"Questions 37–40 · YES / NO / NOT GIVEN","options":["YES","NO","NOT GIVEN"]},{"number":40,"type":"tfng","text":"Hidcote reflects aspects of Johnston''s life experience.","instruction":"Questions 37–40 · YES / NO / NOT GIVEN","options":["YES","NO","NOT GIVEN"]}]'::jsonb,'[["B"],["A"],["D"],["A"],["C"],["D"],["A"],["C"],["G"],["F"],["YES"],["NOT GIVEN"],["NO"],["YES"]]'::jsonb,'draft','[]'::jsonb) on conflict(day_number,ordinal) do update set title=excluded.title,passage_text=excluded.passage_text,question_source=excluded.question_source,questions=excluded.questions,answer_key=excluded.answer_key,status='draft',analysis=excluded.analysis;
